CREATE FUNCTION public.change_provider_subtype(_ws uuid,_subtype text,_confirmed boolean) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE w public.workspaces;BEGIN SELECT * INTO w FROM public.workspaces WHERE id=_ws FOR UPDATE;IF _confirmed IS DISTINCT FROM true OR _subtype NOT IN ('nemt_business','independent_contractor') OR w.id IS NULL OR w.account_type<>'provider' OR w.status<>'active' OR w.is_test_account OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.user_profiles p ON p.user_id=m.user_id WHERE m.workspace_id=_ws AND m.user_id=auth.uid() AND m.role='owner' AND NOT m.is_contractor AND m.removed_at IS NULL AND p.status='active' AND NOT p.is_test_account AND p.deleted_at IS NULL) THEN RAISE EXCEPTION 'Confirmed active provider owner required';END IF;IF w.provider_subtype=_subtype THEN RETURN;END IF;PERFORM set_config('app.provider_subtype_write','true',true);UPDATE public.workspaces SET provider_subtype=_subtype,provider_subtype_selected_at=now() WHERE id=_ws;INSERT INTO public.account_relationship_events(workspace_id,action,actor_id,details) VALUES(_ws,'provider_subtype_changed',auth.uid(),jsonb_build_object('before',w.provider_subtype,'after',_subtype,'confirmation',true,'eligibility_granted',false));END $$;
REVOKE ALL ON FUNCTION public.change_provider_subtype(uuid,text,boolean) FROM PUBLIC,anon;GRANT EXECUTE ON FUNCTION public.change_provider_subtype(uuid,text,boolean) TO authenticated;
CREATE FUNCTION public.provider_driver_available(_driver uuid,_ws uuid,_service text,_date date) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.drivers d WHERE d.id=_driver AND d.workspace_id=_ws AND d.status='active' AND _service=ANY(d.service_capabilities) AND (d.license_expiry IS NULL OR d.license_expiry>=_date) AND NOT public.driver_on_vacation(d.id,_date)) $$;
REVOKE ALL ON FUNCTION public.provider_driver_available(uuid,uuid,text,date) FROM PUBLIC,anon,authenticated;GRANT EXECUTE ON FUNCTION public.provider_driver_available(uuid,uuid,text,date) TO service_role;
CREATE OR REPLACE FUNCTION public.patient_driver_suggestion(_patient uuid,_service text DEFAULT 'ambulatory',_date date DEFAULT current_date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE p public.saved_patients;chosen uuid;prior uuid;warning text;opts jsonb;BEGIN SELECT * INTO p FROM public.saved_patients WHERE id=_patient AND active AND kind='patient';IF p.id IS NULL OR p.workspace_id IS NULL OR _service NOT IN ('ambulatory','wheelchair','stretcher') OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id JOIN public.user_profiles u ON u.user_id=m.user_id WHERE m.workspace_id=p.workspace_id AND m.user_id=auth.uid() AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND w.account_type='provider' AND NOT w.is_test_account AND u.status='active' AND NOT u.is_test_account) THEN RAISE EXCEPTION 'Authorized provider patient required';END IF;
SELECT coalesce(jsonb_agg(jsonb_build_object('id',d.id,'name',concat_ws(' ',d.first_name,d.last_name)) ORDER BY d.last_name),'[]') INTO opts FROM public.drivers d WHERE public.provider_driver_available(d.id,p.workspace_id,_service,_date) AND public.business_record_access(p.workspace_id,'drivers',d.id,'read');
SELECT t.driver_id INTO prior FROM public.trips t JOIN public.ride_requests r ON r.id=t.ride_request_id WHERE r.saved_patient_id=p.id AND r.workspace_id=p.workspace_id AND t.status='completed' AND t.completed_at IS NOT NULL AND public.provider_driver_available(t.driver_id,p.workspace_id,_service,_date) AND public.business_record_access(p.workspace_id,'drivers',t.driver_id,'read') ORDER BY t.completed_at DESC,t.id DESC LIMIT 1;
IF p.preferred_driver_id IS NOT NULL THEN IF public.provider_driver_available(p.preferred_driver_id,p.workspace_id,_service,_date) AND public.business_record_access(p.workspace_id,'drivers',p.preferred_driver_id,'read') THEN chosen:=p.preferred_driver_id;ELSE warning:='No eligible preferred driver';END IF;ELSE chosen:=prior;END IF;
RETURN jsonb_build_object('driverId',chosen,'warning',warning,'source',CASE WHEN chosen IS NULL THEN 'unassigned' WHEN chosen=p.preferred_driver_id THEN 'preferred' ELSE 'last_completed' END,'preferredDriverId',p.preferred_driver_id,'lastDriverId',prior,'options',opts);END $$;
ALTER TABLE public.ride_requests ADD COLUMN confirmed_provider_driver_id uuid REFERENCES public.drivers(id);
COMMENT ON COLUMN public.ride_requests.confirmed_provider_driver_id IS 'Explicit provider confirmation at owned-trip submission only; never assigned by suggestion reads.';
CREATE FUNCTION public.confirmed_provider_driver_guard() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF TG_OP='UPDATE' AND NEW.confirmed_provider_driver_id IS DISTINCT FROM OLD.confirmed_provider_driver_id THEN RAISE EXCEPTION 'Driver confirmation is immutable after submission';END IF;IF NEW.confirmed_provider_driver_id IS NOT NULL AND TG_OP='INSERT' THEN IF NOT NEW.provider_owned_operation OR NEW.saved_patient_id IS NULL OR NEW.is_test OR NOT EXISTS(SELECT 1 FROM public.workspace_members m JOIN public.workspaces w ON w.id=m.workspace_id WHERE m.workspace_id=NEW.workspace_id AND m.user_id=NEW.actor_user_id AND m.role IN ('owner','admin') AND NOT m.is_contractor AND m.removed_at IS NULL AND w.status='active' AND w.account_type='provider' AND NOT w.is_test_account) OR NOT EXISTS(SELECT 1 FROM public.saved_patients WHERE id=NEW.saved_patient_id AND workspace_id=NEW.workspace_id AND active) OR NOT public.provider_driver_available(NEW.confirmed_provider_driver_id,NEW.workspace_id,CASE WHEN NEW.transport_type='gurney' THEN 'stretcher' ELSE NEW.transport_type END,NEW.pickup_date) THEN RAISE EXCEPTION 'Eligible workspace driver and explicit provider-owned patient trip required';END IF;END IF;RETURN NEW;END $$;
CREATE TRIGGER zzzza_confirmed_provider_driver BEFORE INSERT OR UPDATE ON public.ride_requests FOR EACH ROW EXECUTE FUNCTION public.confirmed_provider_driver_guard();
CREATE OR REPLACE FUNCTION public.create_owned_provider_operation() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE tid uuid;BEGIN IF NEW.provider_owned_operation AND NOT NEW.is_test AND NEW.trip_kind='passenger' AND NEW.transport_type<>'delivery' THEN tid:=public.promote_ride_request_to_trip(NEW.id);IF tid IS NULL THEN RAISE EXCEPTION 'Owned trip unavailable';END IF;IF NEW.confirmed_provider_driver_id IS NOT NULL THEN UPDATE public.trips SET driver_id=NEW.confirmed_provider_driver_id WHERE id=tid;END IF;IF NEW.customer_quote_draft_id IS NOT NULL THEN UPDATE public.trip_drafts SET submitted_trip_id=tid WHERE id=NEW.customer_quote_draft_id AND user_id=NEW.actor_user_id AND submitted_trip_id IS NULL;END IF;END IF;RETURN NEW;END $$;